function clearHelpSearchHighlights() {
  helpGuideContent
    .querySelectorAll("mark[data-help-highlight]")
    .forEach(mark => {
      mark.replaceWith(
        document.createTextNode(
          mark.textContent
        )
      );
    });

  helpGuideContent.normalize();
}

function highlightHelpMatches(
  section,
  query
) {
  if (!query) return;

  const escaped =
    query.replace(
      /[.*+?^${}()|[\]\\]/g,
      "\\$&"
    );

  const expression =
    new RegExp(
      escaped,
      "gi"
    );

  const walker =
    document.createTreeWalker(
      section,
      NodeFilter.SHOW_TEXT,
      {
        acceptNode(node) {
          if (
            !node.nodeValue
              .toLowerCase()
              .includes(
                query.toLowerCase()
              )
          ) {
            return NodeFilter.FILTER_REJECT;
          }

          if (
            node.parentElement?.closest(
              "script, style, mark"
            )
          ) {
            return NodeFilter.FILTER_REJECT;
          }

          return NodeFilter.FILTER_ACCEPT;
        }
      }
    );

  const nodes = [];

  while (walker.nextNode()) {
    nodes.push(
      walker.currentNode
    );
  }

  nodes.forEach(node => {
    const text =
      node.nodeValue;

    let lastIndex = 0;
    let match;
    const fragment =
      document.createDocumentFragment();

    expression.lastIndex = 0;

    while (
      (
        match =
          expression.exec(text)
      )
    ) {
      if (
        match.index >
        lastIndex
      ) {
        fragment.append(
          document.createTextNode(
            text.slice(
              lastIndex,
              match.index
            )
          )
        );
      }

      const mark =
        document.createElement(
          "mark"
        );

      mark.dataset.helpHighlight =
        "true";

      mark.textContent =
        match[0];

      fragment.append(mark);

      lastIndex =
        match.index +
        match[0].length;

      if (
        match[0].length === 0
      ) {
        expression.lastIndex += 1;
      }
    }

    if (
      lastIndex <
      text.length
    ) {
      fragment.append(
        document.createTextNode(
          text.slice(
            lastIndex
          )
        )
      );
    }

    node.replaceWith(fragment);
  });
}

function selectHelpTopic(
  id,
  {
    scroll = true
  } = {}
) {
  const target =
    document.getElementById(id);

  if (
    !target ||
    target.classList.contains(
      "search-hidden"
    )
  ) {
    return;
  }

  helpGuideNav
    .querySelectorAll(
      ".help-nav-item"
    )
    .forEach(button => {
      button.classList.toggle(
        "active",
        button.dataset.helpTarget ===
          id
      );
    });

  if (scroll) {
    target.scrollIntoView({
      behavior: "smooth",
      block: "start"
    });
  }
}

function filterHelpGuide() {
  clearHelpSearchHighlights();

  const query =
    helpGuideSearch.value
      .trim()
      .toLowerCase();

  clearHelpGuideSearch.hidden =
    !query;

  const sections =
    [...helpGuideContent.querySelectorAll(
      "[data-help-topic]"
    )];

  let matches = 0;

  sections.forEach(section => {
    const haystack =
      section.textContent
        .toLowerCase();

    const visible =
      !query ||
      haystack.includes(query);

    section.classList.toggle(
      "search-hidden",
      !visible
    );

    const navButton =
      helpGuideNav.querySelector(
        `[data-help-target="${section.id}"]`
      );

    navButton?.classList.toggle(
      "search-hidden",
      !visible
    );

    if (visible) {
      matches += 1;

      if (query) {
        highlightHelpMatches(
          section,
          query
        );
      }
    }
  });

  helpNoResults.hidden =
    matches !== 0;

  helpSearchSummary.hidden =
    !query ||
    matches === 0;

  if (
    query &&
    matches > 0
  ) {
    helpSearchSummary.textContent =
      `${matches} help topic${matches === 1 ? "" : "s"} matching “${helpGuideSearch.value.trim()}”`;

    const firstVisible =
      sections.find(section =>
        !section.classList.contains(
          "search-hidden"
        )
      );

    if (firstVisible) {
      selectHelpTopic(
        firstVisible.id,
        { scroll: false }
      );

      helpGuideContent.scrollTop =
        0;
    }
  } else if (!query) {
    sections.forEach(section =>
      section.classList.remove(
        "search-hidden"
      )
    );

    helpGuideNav
      .querySelectorAll(
        ".help-nav-item"
      )
      .forEach(button =>
        button.classList.remove(
          "search-hidden"
        )
      );

    selectHelpTopic(
      "getting-started",
      { scroll: false }
    );
  }
}

function openHelpGuide(
  topic = "getting-started"
) {
  helpGuideModal.hidden =
    false;

  helpGuideSearch.value =
    "";

  filterHelpGuide();

  requestAnimationFrame(() => {
    selectHelpTopic(
      topic,
      { scroll: false }
    );

    helpGuideContent.scrollTop =
      0;

    helpGuideSearch.focus();
  });
}

function closeHelpGuide() {
  helpGuideModal.hidden =
    true;

  helpGuideSearch.value =
    "";

  filterHelpGuide();
}

