document.addEventListener(
  "keydown",
  event => {
    const tag =
      event.target?.tagName
        ?.toLowerCase();

    const typing =
      tag === "input" ||
      tag === "textarea" ||
      tag === "select" ||
      event.target?.isContentEditable;

    if (
      !typing &&
      event.key === "F11"
    ) {
      event.preventDefault();
      toggleAppFullscreen();
      return;
    }


  },
  true
);

document.addEventListener("keydown", event => {
  const keyboardTarget = event.target;
  const keyboardTyping = Boolean(
    keyboardTarget?.closest?.(
      "input, textarea, select, [contenteditable='true']"
    )
  );

  if (shapeQuickMenuOpen) {
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      closeShapeQuickMenu();
      return;
    }

    const quickChoice = shapeQuickMenuItems.find(
      item => item.code === event.code || item.key === event.key
    );

    if (quickChoice) {
      event.preventDefault();
      event.stopPropagation();
      chooseShapeFromQuickMenu(quickChoice.tool);
      return;
    }

    /* Any unrelated command closes the transient picker first. */
    if (!event.shiftKey && !["Shift", "Control", "Alt", "Meta"].includes(event.key)) {
      closeShapeQuickMenu();
    }
  }

  if (drawingQuickMenuOpen) {
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      closeDrawingQuickMenu();
      return;
    }

    const quickChoice = drawingQuickMenuItems.find(
      item => item.code === event.code || item.key === event.key
    );

    if (quickChoice) {
      event.preventDefault();
      event.stopPropagation();
      chooseDrawingFromQuickMenu(quickChoice);
      return;
    }

    if (!event.shiftKey && !["Shift", "Control", "Alt", "Meta"].includes(event.key)) {
      closeDrawingQuickMenu();
    }
  }

  if (
    !keyboardTyping &&
    event.shiftKey &&
    !event.ctrlKey &&
    !event.metaKey &&
    !event.altKey &&
    event.key.toLowerCase() === "s"
  ) {
    event.preventDefault();
    event.stopPropagation();
    openShapeQuickMenu();
    return;
  }

  if (
    !keyboardTyping &&
    event.shiftKey &&
    !event.ctrlKey &&
    !event.metaKey &&
    !event.altKey &&
    event.key.toLowerCase() === "d"
  ) {
    event.preventDefault();
    event.stopPropagation();
    openDrawingQuickMenu();
    return;
  }

  if (
    curvatureIsActive() &&
    curvaturePath &&
    (
      event.ctrlKey ||
      event.metaKey
    ) &&
    !event.shiftKey &&
    event.key.toLowerCase() ===
      "z"
  ) {
    if (
      curvatureUndoLastPlacement()
    ) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
  }

  if (
    event.key.toLowerCase() === "c" &&
    event.shiftKey &&
    !event.ctrlKey &&
    !event.metaKey &&
    !event.altKey
  ) {
    setTool("curvature");
    event.preventDefault();
    return;
  }


  if (
    curvatureIsActive()
  ) {
    if (
      event.key ===
        "Escape"
    ) {
      if (
        curvaturePath
      ) {
        curvatureFinishPath(
          false
        );
      }

      curvatureHover =
        null;

      curvatureDrag =
        null;

      drawSelection();

      event.preventDefault();
      return;
    }

    if (
      event.key ===
        "Enter" &&
      curvaturePath
    ) {
      curvatureFinishPath(
        false
      );

      event.preventDefault();
      return;
    }

    if (
      event.key.toLowerCase() ===
        "c" &&
      event.shiftKey &&
      !event.ctrlKey &&
      !event.metaKey &&
      !event.altKey
    ) {
      setTool(
        "curvature"
      );

      event.preventDefault();
      return;
    }
  }

  const element = document.activeElement;

  if (
    event.key === "F1" &&
    !helpGuideModal.hidden
  ) {
    event.preventDefault();
    return;
  }

  if (
    event.key === "F1"
  ) {
    event.preventDefault();
    openHelpGuide();
    return;
  }

  if (["INPUT", "SELECT", "TEXTAREA"].includes(element.tagName)) return;

  if (event.ctrlKey || event.metaKey) {
    const key = event.key.toLowerCase();

    if (key === "c" && !event.shiftKey) {
      event.preventDefault();
      copySelected();
      return;
    }

    if (key === "x" && !event.shiftKey) {
      event.preventDefault();
      cutSelected();
      return;
    }

    if (key === "v" && !event.shiftKey) {
      event.preventDefault();
      pasteClipboard();
      return;
    }

    if (key === "z" && event.shiftKey) {
      event.preventDefault();
      redo();
      return;
    }

    if (key === "z") {
      event.preventDefault();
      undo();
      return;
    }

    if (key === "y") {
      event.preventDefault();
      redo();
      return;
    }

    if (key === "h") {
      event.preventDefault();
      showHistoryPanel();
      return;
    }

    if (key === "g" && event.shiftKey) {
      event.preventDefault();
      ungroupSelected();
      return;
    }

    if (key === "g") {
      event.preventDefault();
      groupSelected();
      return;
    }

    if (
      key === "d" &&
      event.shiftKey
    ) {
      event.preventDefault();
      repeatLastAction();
      return;
    }

    if (key === "d") {
      event.preventDefault();
      duplicateSelected();
    }
    if (key === "e") {
      event.preventDefault();
      openExportModal();
    }
    if (key === "n") {
      event.preventDefault();
      runCommand("new");
    }
    if (key === "s") {
      event.preventDefault();
      saveProject();
    }
    if (key === "o") {
      event.preventDefault();
      openProjectPicker();
    }
    return;
  }

  const key = event.key.toLowerCase();

  if (key === "v") setTool("select");
  if (key === "a") setTool("vertex");
  if (key === "m" && event.shiftKey) setTool("shapeBuilder");
  if (key === "p") setTool("pen");
  if (key === "b") setTool("freeDraw");
  if (key === "t") setTool("text");
  if (key === "r") setTool("rect");
  if (key === "e") setTool("ellipse");
  if (key === "l") setTool("line");

  if (event.key === "Enter" && activePath) {
    event.preventDefault();
    finishPath();
    return;
  }

  if (event.key === "Escape") {
    if (
      radialRepeatCenterPick
    ) {
      radialRepeatCenterPick =
        null;

      clearSnapGuides();

      document
        .querySelectorAll(
          ".radial-repeat-tool"
        )
        .forEach(
          button =>
            button.classList.remove(
              "active"
            )
        );

      svg.style.cursor =
        activeTool === "select"
          ? "default"
          : "crosshair";

      toolStatus.textContent =
        "Radial Repeat cancelled";

      event.preventDefault();
      return;
    }

    if (
      perspective2Draw
    ) {
      perspective2Draw =
        null;
      drawPerspective2Grid();
      event.preventDefault();
      return;
    }

    if (
      perspective2Drag
    ) {
      perspective2Drag =
        null;
      drawPerspective2Grid();
      event.preventDefault();
      return;
    }

    if (
      imageCropTarget
    ) {
      cancelImageCrop();
      event.preventDefault();
      return;
    }

    if (
      freeDrawPointerId !== null
    ) {
      cancelFreeDrawStroke();
      toolStatus.textContent =
        "Free Draw: cancelled";
      return;
    }

    closeCanvasContextMenu();
    closeCanvasTabContextMenu();

    if (activeTextEdit) {
      finishTextEditing(false);
      return;
    }

    if (textCreateDrag) {
      textCreateDrag.guide?.remove();
      textCreateDrag = null;
      return;
    }

    if (shapeBuilderDrawing) {
      shapeBuilderDrawing = false;
      shapeBuilderPoints = [];
      shapeBuilderHits = [];
      shapeBuilderSubtracting = false;
      resetShapeBuilderRegions();
      drawSelection();
    } else if (activePath) {
      finishPath();
    } else if (pendingShape) {
      pendingShape.remove();
      pendingShape = null;
      startPoint = null;
      selected = null;
      selectedItems = [];
      selectionOverlay.innerHTML = "";
      renderLayers();
    } else {
      deselect();
    }
    return;
  }

  if (event.key === "Delete" || event.key === "Backspace") {
    deleteSelected();
  }
});

/* ---------------- PATH PARSER ----------------
   Used for duplicated/exported paths created by this editor.
*/
function parseSimpleCubicPath(d) {
  if (!d) return [];
  const nums = (d.match(/-?\d*\.?\d+(?:e[-+]?\d+)?/gi) || []).map(Number);
  const anchors = [];
  if (nums.length < 2) return anchors;

  anchors.push({
    x: nums[0], y: nums[1],
    inX: nums[0], inY: nums[1],
    outX: nums[0], outY: nums[1]
  });

  let i = 2;
  while (i + 5 < nums.length) {
    const prev = anchors[anchors.length - 1];
    prev.outX = nums[i];
    prev.outY = nums[i + 1];

    anchors.push({
      inX: nums[i + 2],
      inY: nums[i + 3],
      x: nums[i + 4],
      y: nums[i + 5],
      outX: nums[i + 4],
      outY: nums[i + 5]
    });

    i += 6;
  }

  return anchors;
}

function capitalize(text) {
  return text.charAt(0).toUpperCase() + text.slice(1);
}

function propertySectionKey(section, title) {
  if (section.id) {
    return section.id;
  }

  return (
    "property-" +
    title
      .toLowerCase()
      .replace(/&/g, "and")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "")
  );
}

function initializeCollapsiblePropertySections() {
  const sections = [
    ...propertiesView.querySelectorAll(":scope > .panel-section")
  ];

  const defaultOpenTitles = new Set([
    "Transform",
    "Appearance"
  ]);

  sections.forEach(section => {
    if (section.dataset.collapsibleReady === "true") {
      return;
    }

    const existingHeading =
      section.querySelector(":scope > h3") ||
      section.querySelector(":scope > .transform-heading");

    if (!existingHeading) return;

    const headingText =
      existingHeading.matches("h3")
        ? existingHeading.textContent.trim()
        : existingHeading.querySelector("h3")?.textContent.trim();

    if (!headingText) return;

    const sectionKey = propertySectionKey(
      section,
      headingText
    );

    const storageKey =
      `vector-studio-property-section:${sectionKey}`;

    let open = defaultOpenTitles.has(headingText);

    try {
      const stored = localStorage.getItem(storageKey);

      if (stored === "open") open = true;
      if (stored === "closed") open = false;
    } catch {
      // Storage can be unavailable in restricted/local contexts.
    }

    const header = document.createElement("div");
    header.className = "panel-section-header";

    const toggle = document.createElement("button");
    toggle.type = "button";
    toggle.className = "panel-section-toggle";
    toggle.setAttribute(
      "aria-expanded",
      open ? "true" : "false"
    );

    const chevron = document.createElement("span");
    chevron.className = "panel-section-chevron";
    chevron.textContent = "›";

    const title = document.createElement("span");
    title.className = "panel-section-title";
    title.textContent = headingText;

    toggle.append(
      chevron,
      title
    );

    header.appendChild(toggle);

    /*
     * Transform already has the aspect-ratio link button in its heading.
     * Keep it as a header accessory rather than burying it inside the body.
     */
    if (existingHeading.matches(".transform-heading")) {
      const accessory =
        existingHeading.querySelector("#transformLockAspect");

      if (accessory) {
        accessory.classList.add("panel-section-accessory");
        header.appendChild(accessory);
      }
    }

    const body = document.createElement("div");
    body.className = "panel-section-body";

    const children = [...section.children];

    children.forEach(child => {
      if (child !== existingHeading) {
        body.appendChild(child);
      }
    });

    existingHeading.remove();

    section.replaceChildren(
      header,
      body
    );

    section.dataset.collapsibleReady = "true";
    section.dataset.sectionKey = sectionKey;
    section.classList.toggle(
      "collapsed",
      !open
    );

    toggle.addEventListener("click", () => {
      const nextOpen =
        section.classList.contains("collapsed");

      section.classList.toggle(
        "collapsed",
        !nextOpen
      );

      toggle.setAttribute(
        "aria-expanded",
        nextOpen ? "true" : "false"
      );

      try {
        localStorage.setItem(
          storageKey,
          nextOpen ? "open" : "closed"
        );
      } catch {
        // Ignore storage errors.
      }
    });
  });
}

