function positionRightPanelTabRailBelowHeader() {
  const rail =
    document.querySelector(
      "#rightPanelTabRail"
    );

  if (!rail) return;

  /*
   * The rail now lives inside #rightPanel and is positioned relative to that
   * panel, so no viewport/header offset calculation is required.
   */
  rail.style.top =
    "0px";

  rail.style.right =
    "0px";
}




function initializeRightPanelTabs() {
  const rail =
    document.querySelector(
      "#rightPanelTabRail"
    );

  if (
    !rail ||
    rail.dataset.clickBound ===
      "true"
  ) {
    return;
  }

  rail.dataset.clickBound =
    "true";

  let dragState =
    null;

  const finishDrag =
    event => {
      if (
        !dragState ||
        event.pointerId !==
          dragState.pointerId
      ) {
        return;
      }

      const {
        tab,
        dragging
      } =
        dragState;

      try {
        tab.releasePointerCapture?.(
          event.pointerId
        );
      } catch {}

      tab.classList.remove(
        "dragging"
      );

      if (
        !dragging
      ) {
        if (dragState.shiftKey || event.shiftKey) {
          shiftSelectRightPanel(tab.dataset.panelView);
        } else {
          showRightPanel(tab.dataset.panelView);
        }
      }

      dragState =
        null;

      event.preventDefault();
      event.stopPropagation();
    };

  rail.addEventListener(
    "pointerdown",
    event => {
      const tab =
        event.target.closest(
          ".right-panel-tab"
        );

      if (
        !tab ||
        event.button !== 0
      ) {
        return;
      }

      dragState = {
        tab,
        pointerId:
          event.pointerId,
        startX:
          event.clientX,
        startY:
          event.clientY,
        dragging:
          false,
        shiftKey:
          event.shiftKey
      };

      tab.setPointerCapture?.(
        event.pointerId
      );

      event.preventDefault();
      event.stopPropagation();
    }
  );

  rail.addEventListener(
    "pointermove",
    event => {
      if (
        !dragState ||
        event.pointerId !==
          dragState.pointerId
      ) {
        return;
      }

      const distance =
        Math.hypot(
          event.clientX -
            dragState.startX,
          event.clientY -
            dragState.startY
        );

      if (
        !dragState.dragging &&
        distance >= 6
      ) {
        dragState.dragging =
          true;

        dragState.tab.classList.add(
          "dragging"
        );
      }

      if (
        !dragState.dragging
      ) {
        return;
      }

      const candidates =
        [
          ...rail.querySelectorAll(
            ".right-panel-tab:not(.dragging)"
          )
        ];

      const beforeTab =
        candidates.find(
          tab => {
            const rect =
              tab.getBoundingClientRect();

            return (
              event.clientY <
              rect.top +
                rect.height / 2
            );
          }
        );

      rail.insertBefore(
        dragState.tab,
        beforeTab ||
        null
      );

      event.preventDefault();
      event.stopPropagation();
    }
  );

  rail.addEventListener(
    "pointerup",
    finishDrag
  );

  rail.addEventListener(
    "pointercancel",
    event => {
      if (
        !dragState ||
        event.pointerId !==
          dragState.pointerId
      ) {
        return;
      }

      dragState.tab.classList.remove(
        "dragging"
      );

      dragState =
        null;
    }
  );

  /*
   * Suppress the synthetic click generated after pointerup.
   * Activation is handled directly in finishDrag().
   */
  rail.addEventListener(
    "click",
    event => {
      if (
        event.target.closest(
          ".right-panel-tab"
        )
      ) {
        event.preventDefault();
        event.stopPropagation();
      }
    }
  );
}







